// Totals are kept per cart content across renders and screens (the cart re-renders on every keystroke of the coupon field).
const totals = new Map<string, number>();

// The lines and how many items they hold.
export const cartKey = (items: CartItem[]): string => `${items.map(i => i.id).join(',')}|${items.reduce((n, i) => n + i.qty, 0)}`;

